  let pin = band(fract(s.uv.x / 0.02) * 0.02, 0.01, 0.002);

  var paper = vec3f(0.47, 0.4, 0.27) * (1.0 - 0.07 * pin);
  paper = mix(paper, vec3f(0.12, 0.2, 0.09) * (0.8 + 0.4 * petal), leaf);
