  let row = floor((h - 1.1) / 0.5);
  let cell = vec2f(s.uv.x + 0.45 * row, h - 1.1) / vec2f(0.9, 0.5);
  let spot = inside(length((fract(cell) - 0.5) * vec2f(0.9, 0.5)) - 0.17);
