  colour = mix(colour, vec3f(0.03, 0.13, 0.42), river);
  colour = mix(colour, vec3f(0.62, 0.45, 0.03), step_);
  let fleck = mix(0.7, 1.25, crumb.y) * (0.7 + 0.5 * crumb.x);
