  let mark =
    inside(length(vec2f(x, y - 0.03 - tall * 0.55)) - min(width, tall) * 0.16);
  let print =
    mix(
      mix(colour, vec3f(0.62, 0.6, 0.52), label),
      branded(unitOf(facing) + 0.37),
      mark,
    );
