  var albedo =
    mix(mix(red, slab, bared), vec3f(0.55, 0.4, 0.03), line * (1.0 - bared));
  albedo *= tracked * (1.0 - 0.7 * cut);
  let gloss = mix(0.88, 0.25, bared) * (0.75 + 0.25 * tracked);
